# usage: probe.py file.dae x y  -> z of all triangles covering (x,y), per node
import sys, xml.etree.ElementTree as ET
ns={'c':'http://www.collada.org/2005/11/COLLADASchema'}
r=ET.parse(sys.argv[1]).getroot(); X,Y=float(sys.argv[2]),float(sys.argv[3])
def mm(A,B): return [[sum(A[i][k]*B[k][j] for k in range(4)) for j in range(4)] for i in range(4)]
I=[[float(i==j) for j in range(4)] for i in range(4)]
geo={g.get('id'):g for g in r.findall('.//c:geometry',ns)}
def tris(g):
    mesh=g.find('c:mesh',ns)
    srcs={s.get('id'):list(map(float,s.find('c:float_array',ns).text.split())) for s in mesh.findall('c:source',ns)}
    vpos=mesh.find('c:vertices',ns); psrc=vpos.find('c:input[@semantic="POSITION"]',ns).get('source')[1:]
    P=srcs[psrc]; P=[P[i:i+3] for i in range(0,len(P),3)]
    for prim in list(mesh.findall('c:triangles',ns))+list(mesh.findall('c:polylist',ns)):
        inputs=prim.findall('c:input',ns); stride=max(int(i.get('offset')) for i in inputs)+1
        voff=[int(i.get('offset')) for i in inputs if i.get('semantic')=='VERTEX'][0]
        idx=list(map(int,prim.find('c:p',ns).text.split()))
        vc=prim.find('c:vcount',ns)
        counts=list(map(int,vc.text.split())) if vc is not None else [3]*(len(idx)//stride//3)
        pos=0
        for c in counts:
            poly=[P[idx[(pos+k)*stride+voff]] for k in range(c)]; pos+=c
            for k in range(1,c-1): yield (poly[0],poly[k],poly[k+1])
def walk(n,M):
    L=I; m=n.find('c:matrix',ns)
    if m is not None:
        v=list(map(float,m.text.split())); L=[v[i*4:i*4+4] for i in range(4)]
    W=mm(M,L)
    for ig in n.findall('c:instance_geometry',ns):
        zs=[]
        for t in tris(geo[ig.get('url')[1:]]):
            T=[[sum(W[i][k]*p[k] for k in range(3))+W[i][3] for i in range(3)] for p in t]
            (x1,y1,z1),(x2,y2,z2),(x3,y3,z3)=T
            d=(y2-y3)*(x1-x3)+(x3-x2)*(y1-y3)
            if abs(d)<1e-12: continue
            a=((y2-y3)*(X-x3)+(x3-x2)*(Y-y3))/d; b=((y3-y1)*(X-x3)+(x1-x3)*(Y-y3))/d; c=1-a-b
            if min(a,b,c)>=-1e-9: zs.append(round(a*z1+b*z2+c*z3,4))
        if zs: print(n.get('id'), sorted(set(zs)))
    for c in n.findall('c:node',ns): walk(c,W)
for n in r.findall('.//c:visual_scene/c:node',ns): walk(n,I)
